test("same-size journal replacement preserving mtime invalidates the reader transaction view", () => {
	const f = fixture();
	try {
		const original = f.read("docs/repo-wiki/auth.md");
		const alternate = original.replaceAll("令牌认证", "会话机制");
		const relative = ".lumine/wiki-state/transactions/replace.json";
		const file = path.join(f.root, relative), temporary = `${file}.tmp`;
		const journal = (before) => ({
			schemaVersion: 1,
			id: "replace",
			status: "pending",
			mutations: [{
				path: "docs/repo-wiki/auth.md",
				before,
				after: original
			}]
		});
		f.put(relative, journal(original));
		utimesSync(file, 1e9, 1e9);
		const first = statSync(file, { bigint: true });
		assert.equal(showKnowledge(f.root, "auth").title, "令牌认证");
		writeFileSync(temporary, JSON.stringify(journal(alternate)));
		utimesSync(temporary, 1e9, 1e9);
		renameSync(temporary, file);
		const second = statSync(file, { bigint: true });
		assert.equal(second.size, first.size);
		assert.equal(second.mtimeNs, first.mtimeNs);
		assert.notEqual(second.ino, first.ino);
		assert.equal(showKnowledge(f.root, "auth").title, "会话机制");
	} finally {
		f.close();
	}
});
test("CLI exposes localized task context, JSON impact and the exact public help", () => {
	const f = fixture();
	try {
		const extension = import.meta.url.endsWith(".mjs") ? "mjs" : "ts";
		const cli = fileURLToPath(new URL(`../wiki.${extension}`, import.meta.url)), loader = extension === "ts" ? ["--import", "tsx"] : [];
		const run = (...args) => spawnSync(process.execPath, [
			...loader,
			cli,
			...args,
			"--root",
			f.root
		], { encoding: "utf8" });
		const context = run("context", "令牌认证", "--reference", "auth", "--json");
		assert.equal(context.status, 0, context.stderr);
		assert.equal(JSON.parse(context.stdout).question, "令牌认证");
		const prose = run("context", "令牌认证");
		assert.equal(prose.status, 0, prose.stderr);
		assert.match(prose.stdout, /任务背景/);
		assert.match(prose.stdout, /完整读取/);
		const impact = run("impact", "library:src/auth.ts", "--json");
		assert.equal(impact.status, 0, impact.stderr);
		assert.ok(JSON.parse(impact.stdout).candidateOnly);
		const help = run("--help", "--json");
		assert.equal(help.status, 0);
		assert.ok(JSON.parse(help.stdout).commands.some((command) => command.startsWith("wiki context")));
		const invalid = run("impact", "src/auth.ts", "--json");
		assert.equal(invalid.status, 1);
		assert.equal(JSON.parse(invalid.stderr).code, "IMPACT_PATH_INVALID");
	} finally {
		f.close();
	}
});
